// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// PostAuthForgotPassword Send a reset link when the address is known; the answer is the same either way. Public, rate limited.
	// (POST /api/auth/forgot-password)
	PostAuthForgotPassword(ctx context.Context, request PostAuthForgotPasswordRequestObject) (PostAuthForgotPasswordResponseObject, error)
	// PostAuthLogin Exchange credentials for a session: the access token in the body, the refresh token as an HttpOnly cookie. Every failure is one 401. Public, rate limited.
	// (POST /api/auth/login)
	PostAuthLogin(ctx context.Context, request PostAuthLoginRequestObject) (PostAuthLoginResponseObject, error)
	// PostAuthLogout Revoke every refresh token of the person and expire the cookie.
	// (POST /api/auth/logout)
	PostAuthLogout(ctx context.Context, request PostAuthLogoutRequestObject) (PostAuthLogoutResponseObject, error)
	// PostAuthRefresh Rotate the refresh cookie and issue a new access token. A reused token revokes its whole family. No cookie at all is a 204, not a 401: a first visit asks this, and there is simply nothing to restore.
	// (POST /api/auth/refresh)
	PostAuthRefresh(ctx context.Context, request PostAuthRefreshRequestObject) (PostAuthRefreshResponseObject, error)
	// PostAuthRegister Create an account and a pending workspace and send the verification link - or, for an address that has an account, mail its owner instead. The answer is the same either way. Public, rate limited.
	// (POST /api/auth/register)
	PostAuthRegister(ctx context.Context, request PostAuthRegisterRequestObject) (PostAuthRegisterResponseObject, error)
	// PostAuthResetPassword Consume a reset token, set the password, revoke every session. Public.
	// (POST /api/auth/reset-password)
	PostAuthResetPassword(ctx context.Context, request PostAuthResetPasswordRequestObject) (PostAuthResetPasswordResponseObject, error)
	// PostAuthSwitchTenant Re-issue the session for another workspace the person belongs to. Requires the refresh cookie and a bearer token.
	// (POST /api/auth/switch-tenant)
	PostAuthSwitchTenant(ctx context.Context, request PostAuthSwitchTenantRequestObject) (PostAuthSwitchTenantResponseObject, error)
	// PostAuthVerify Consume a verification token: the account and its workspace become active. Public.
	// (POST /api/auth/verify)
	PostAuthVerify(ctx context.Context, request PostAuthVerifyRequestObject) (PostAuthVerifyResponseObject, error)
	// GetProfileShow The caller's own account. Any authenticated person; no permission.
	// (GET /api/profile)
	GetProfileShow(ctx context.Context, request GetProfileShowRequestObject) (GetProfileShowResponseObject, error)
	// PatchProfileUpdate Change display name or locale. Requires `identity.profile.manage`.
	// (PATCH /api/profile)
	PatchProfileUpdate(ctx context.Context, request PatchProfileUpdateRequestObject) (PatchProfileUpdateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

